app.use((req, _res, next) => { const raw=req.headers.cookie??"",entries=Object.fromEntries(raw.split(";").map(v=>v.trim()).filter(Boolean).map(v=>{const n=v.indexOf("=");return[v.slice(0,n),decodeURIComponent(v.slice(n+1))]})); (req as any).cookies=entries; next(); });
