const signupSchema = z.object({ email:z.string().email().max(254), password:z.string().min(10).max(128).regex(/[A-Z]/,"Add an uppercase letter").regex(/[a-z]/,"Add a lowercase letter").regex(/[0-9]/,"Add a number"), name:z.string().trim().min(2).max(80) });
