async function setSession(res:Response,user:{id:string,email:string}) { const sid=randomUUID(),expires=new Date(Date.now()+12*60*60*1000);await pool.query("INSERT INTO sessions(id,user_id,expires_at) VALUES($1,$2,$3)",[sid,user.id,expires]);const token=jwt.sign({email:user.email},jwtSecret,{subject:user.id,jwtid:sid,expiresIn:"12h"});res.cookie("session",token,{httpOnly:true,secure:process.env.NODE_ENV==="production",sameSite:"lax",maxAge:12*60*60*1000,path:"/"}); }
app.get("/health",async(_req,res)=>{try{await pool.query("SELECT 1");res.json({status:"ok",service:"trading-api",database:"connected",mode:"paper",liveTradingEnabled:false,time:new Date().toISOString()});}catch{res.status(503).json({status:"degraded",service:"trading-api",database:"unavailable",mode:"paper",liveTradingEnabled:false});}});
app.post("/api/v1/auth/register",authLimiter,async(req,res,next)=>{try{const v=signupSchema.safeParse(req.body);if(!v.success)return res.status(400).json({error:"Check the registration fields",details:v.error.flatten()});const email=v.data.email.toLowerCase();const hash=await bcrypt.hash(v.data.password,12);const c=await pool.connect();try{await c.query("BEGIN");const u=await c.query("INSERT INTO users(email,password_hash,display_name) VALUES($1,$2,$3) RETURNING id,email,display_name,role",[email,hash,v.data.name]);const user=u.rows[0];const cash=Number(process.env.PAPER_STARTING_CASH??100000);await c.query("INSERT INTO paper_accounts(user_id,starting_cash,cash) VALUES($1,$2,$2)",[user.id,cash]);await c.query("INSERT INTO risk_policies(user_id) VALUES($1)",[user.id]);await c.query("COMMIT");await setSession(res,user);res.status(201).json({user:{id:user.id,email:user.email,name:user.display_name,role:user.role}});}catch(e){await c.query("ROLLBACK");if((e as any).code==="23505")return res.status(409).json({error:"An account already exists for this email"});throw e;}finally{c.release();}}catch(e){next(e);}});
app.post("/api/v1/auth/login",authLimiter,async(req,res,next)=>{try{const v=credentials.safeParse(req.body);if(!v.success)return res.status(400).json({error:"Enter a valid email and password"});const r=await pool.query("SELECT id,email,password_hash,display_name,role FROM users WHERE email=$1",[v.data.email.toLowerCase()]);const user=r.rows[0];if(!user||!await bcrypt.compare(v.data.password,user.password_hash))return res.status(401).json({error:"Email or password is incorrect"});await setSession(res,user);res.json({user:{id:user.id,email:user.email,name:user.display_name,role:user.role}});}catch(e){next(e);}});
app.post("/api/v1/auth/logout",async(req,res)=>{try{const token=(req as any).cookies?.session;if(token){const claims=jwt.verify(token,jwtSecret) as {jti:string};await pool.query("UPDATE sessions SET revoked_at=now() WHERE id=$1",[claims.jti]);}}catch{}res.clearCookie("session",{httpOnly:true,secure:process.env.NODE_ENV==="production",sameSite:"lax",path:"/"});res.status(204).end();});
app.get("/api/v1/auth/me",auth,async(req:AuthedRequest,res,next)=>{try{const r=await pool.query("SELECT id,email,display_name,role FROM users WHERE id=$1",[req.userId]);if(!r.rowCount)return res.status(401).json({error:"Account not found"});const u=r.rows[0];res.json({user:{id:u.id,email:u.email,name:u.display_name,role:u.role}});}catch(e){next(e);}});
