  const rows:any[]=[];let rejected=0;
  for(let i=0;i<count;i++){const ts=Number(data.timestamp[i]),open=Number(data.open[i]),high=Number(data.high[i]),low=Number(data.low[i]),close=Number(data.close[i]),volume=Number(data.volume[i]),eventTime=new Date(ts*1000);if(!Number.isFinite(ts)||!Number.isFinite(eventTime.getTime())||eventTime<from||eventTime>to||![open,high,low,close].every(v=>Number.isFinite(v)&&v>0)||!Number.isFinite(volume)||volume<0||low>Math.min(open,close)||high<Math.max(open,close)){rejected++;continue;}rows.push([instrument.id,eventTime.toISOString(),open,high,low,close,Math.trunc(volume),"DHAN_HISTORICAL"]);}
