function quote(id:string){return instruments.find(i=>i.id===id)??null;}
async function withLatestQuote(i:any){try{let live=inMemoryQuotes.get(i.symbol);if(redisClient?.isReady){const raw=await redisClient.get(`quote:${i.symbol}`);if(raw)live=JSON.parse(raw);}if(live&&Date.now()-Date.parse(live.timestamp)<30000)return{...i,price:Number(live.price),change:Number(live.change??0),asOf:live.timestamp,source:"DHAN_API"};}catch{}return{...i,price:null,change:null,volume:"—",asOf:null,source:"UNAVAILABLE"};}
let pollingDhan=false;
async function pollDhanQuotes(){
 if(pollingDhan)return; pollingDhan=true;
 try{
  const connection=await pool.query("SELECT * FROM dhan_connections WHERE expires_at>now() ORDER BY connected_at DESC LIMIT 1");
  if(!connection.rowCount)return;
  const token=decryptDhanToken(connection.rows[0]),symbols=instruments.filter(i=>dhanScrips[i.symbol]);
  for(let offset=0;offset<symbols.length;offset+=1000){
   const batch=symbols.slice(offset,offset+1000);
   const response=await fetch("https://api.dhan.co/v2/marketfeed/ohlc",{method:"POST",headers:{"access-token":token,"client-id":dhanClientId,"Content-Type":"application/json"},body:JSON.stringify({NSE_EQ:batch.map(i=>Number(dhanScrips[i.symbol]))}),signal:AbortSignal.timeout(10000)});
   if(!response.ok)break;
   const body:any=await response.json();
   for(const i of batch){
    const q=body?.data?.NSE_EQ?.[dhanScrips[i.symbol]],price=Number(q?.last_price),previous=Number(q?.ohlc?.close);
    if(!Number.isFinite(price)||price<=0)continue;
    const snapshot={price,change:previous>0?(price-previous)/previous*100:0,timestamp:new Date().toISOString(),source:"DHAN_API" as const};
    inMemoryQuotes.set(i.symbol,snapshot);
    if(redisClient?.isReady)await redisClient.set(`quote:${i.symbol}`,JSON.stringify(snapshot),{EX:30});
   }
   if(offset+1000<symbols.length)await new Promise(resolve=>setTimeout(resolve,1100));
  }
 }catch(error){console.warn("Dhan quote poll failed:",(error as Error).message);}finally{pollingDhan=false;}
}
async function loadInstrumentCatalogue(){
 const stored=await pool.query("SELECT i.id,i.symbol,i.name,i.exchange,i.sector,d.security_id FROM instruments i JOIN dhan_instruments d ON d.instrument_id=i.id WHERE i.active=true AND d.exchange_segment='NSE_EQ' ORDER BY i.symbol");
 if(!stored.rowCount)return;
 const index=instruments.find(i=>i.kind==="index")!;
 instruments.splice(0,instruments.length,index,...stored.rows.map(r=>({id:r.id,symbol:r.symbol,name:r.name,exchange:r.exchange,sector:r.sector,kind:"equity"})));
 for(const key of Object.keys(dhanScrips))delete dhanScrips[key];
 for(const row of stored.rows)dhanScrips[row.symbol]=row.security_id;
}
async function refreshInstrumentCatalogue(){try{const count=await syncNseMaster(pool);await loadInstrumentCatalogue();console.log(`Dhan NSE equity catalogue synced: ${count}`);}catch(error){console.warn("Instrument sync failed:",(error as Error).message);}}

async function accountFor(userId:string){return pool.query("SELECT * FROM paper_accounts WHERE user_id=$1",[userId]);}
app.get("/api/v1/paper/account",auth,async(req:AuthedRequest,res,next)=>{try{const ar=await accountFor(req.userId!);if(!ar.rowCount)return res.status(404).json({error:"Paper account not found"});const a=ar.rows[0];const pr=await pool.query("SELECT p.instrument_id,p.quantity,p.avg_price,i.symbol,i.name FROM paper_positions p JOIN instruments i ON i.id=p.instrument_id WHERE p.account_id=$1 ORDER BY i.symbol",[a.id]);const positions=await Promise.all(pr.rows.map(async p=>{const q=await withLatestQuote(quote(p.instrument_id)!);const qty=Number(p.quantity),avg=Number(p.avg_price),fresh=q.source==="DHAN_API"&&Number.isFinite(Number(q.price)),value=fresh?qty*Number(q.price):null;return{instrumentId:p.instrument_id,symbol:p.symbol,name:p.name,quantity:qty,avgPrice:avg,lastPrice:fresh?Number(q.price):null,marketValue:value,unrealizedPnl:fresh?(Number(q.price)-avg)*qty:null,markSource:fresh?"DHAN_API":"UNAVAILABLE"};}));const orders=await pool.query("SELECT o.*,i.symbol FROM paper_orders o JOIN instruments i ON i.id=o.instrument_id WHERE o.account_id=$1 ORDER BY o.created_at DESC LIMIT 100",[a.id]);const allPositionsMarked=positions.every(p=>p.marketValue!==null),equity=allPositionsMarked?Number(a.cash)+positions.reduce((s,p)=>s+Number(p.marketValue),0):null;res.json({id:a.id,name:a.name,cash:Number(a.cash),startingCash:Number(a.starting_cash),equity,dayPnl:equity===null?null:equity-Number(a.starting_cash),positions,orders:orders.rows});}catch(e){next(e);}});
const orderSchema=z.object({instrumentId:z.string(),clientOrderId:z.string().uuid().optional(),side:z.enum(["BUY","SELL"]),quantity:z.number().int().min(1).max(10000),type:z.enum(["MARKET","LIMIT"]).default("MARKET"),limitPrice:z.number().positive().optional()});
app.post("/api/v1/paper/orders",auth,async(req:AuthedRequest,res,next)=>{const parsed=orderSchema.safeParse(req.body);if(!parsed.success)return res.status(400).json({error:"Invalid order",details:parsed.error.flatten()});const i=instruments.find(x=>x.id===parsed.data.instrumentId&&x.kind!=="index");if(!i)return res.status(404).json({error:"Choose a supported equity"});const{side,quantity,type,limitPrice}=parsed.data,clientOrderId=parsed.data.clientOrderId??randomUUID();if(parsed.data.clientOrderId){const previous=await pool.query("SELECT o.*,i.symbol FROM paper_orders o JOIN paper_accounts a ON a.id=o.account_id JOIN instruments i ON i.id=o.instrument_id WHERE a.user_id=$1 AND o.client_order_id=$2",[req.userId,clientOrderId]);if(previous.rowCount)return res.status(200).json(previous.rows[0]);}const current=await withLatestQuote(i);if(current.source!=="DHAN_API"||!Number.isFinite(Number(current.price))||Date.now()-Date.parse(current.asOf??"")>30000)return res.status(409).json({error:"No fresh Dhan quote is available. Paper orders are blocked until a verified market price arrives."});const market=Number(current.price),requested=type==="LIMIT"?(limitPrice??market):market;if(type==="LIMIT"&&limitPrice===undefined)return res.status(400).json({error:"Limit price is required"});if((side==="BUY"&&requested<market)||(side==="SELL"&&requested>market))return res.status(409).json({error:"This paper simulator only fills marketable limit orders; resting limit orders are not enabled."});const fill=Number((market*(side==="BUY"?1.0015:.9985)).toFixed(2));if(type==="LIMIT"&&((side==="BUY"&&fill>limitPrice!)||(side==="SELL"&&fill<limitPrice!)))return res.status(409).json({error:"The simulated fill would breach the limit price."});const gross=fill*quantity,fees=Number((gross*.0005).toFixed(2)),deploy=gross+fees,client=await pool.connect();try{await client.query("BEGIN");const ar=await client.query("SELECT * FROM paper_accounts WHERE user_id=$1 FOR UPDATE",[req.userId]);if(!ar.rowCount){await client.query("ROLLBACK");return res.status(404).json({error:"Paper account not found"});}const a=ar.rows[0],posr=await client.query("SELECT * FROM paper_positions WHERE account_id=$1 AND instrument_id=$2 FOR UPDATE",[a.id,i.id]),pos=posr.rows[0],policy=(await client.query("SELECT * FROM risk_policies WHERE user_id=$1",[req.userId])).rows[0]??{max_positions:5,max_deploy_pct:60};const held=await client.query("SELECT instrument_id,quantity FROM paper_positions WHERE account_id=$1",[a.id]),heldQuotes=await Promise.all(held.rows.map(async p=>({quantity:Number(p.quantity),quote:await withLatestQuote(quote(p.instrument_id)!)})));if(heldQuotes.some(p=>p.quote.source!=="DHAN_API"||!Number.isFinite(Number(p.quote.price))||Date.now()-Date.parse(p.quote.asOf??"")>30000)){await client.query("ROLLBACK");return res.status(409).json({error:"Existing paper positions need fresh Dhan marks before risk checks can continue."});}const equity=Number(a.cash)+heldQuotes.reduce((sum,p)=>sum+p.quantity*Number(p.quote.price),0);const maxLoss=Number(a.starting_cash)*Number(policy.daily_loss_pct??2)/100;if(side==="BUY"&&equity-Number(a.starting_cash)<=-maxLoss){await client.query("ROLLBACK");return res.status(409).json({error:"Paper account loss stop reached; new orders are blocked."});}if(side==="BUY"){if(!posr.rowCount&&(await client.query("SELECT count(*) FROM paper_positions WHERE account_id=$1",[a.id])).rows[0].count>=policy.max_positions){await client.query("ROLLBACK");return res.status(409).json({error:`Position limit reached (${policy.max_positions}).`});}const deployed=heldQuotes.reduce((sum,p)=>sum+p.quantity*Number(p.quote.price),0);if(deployed+gross>Number(a.starting_cash)*Number(policy.max_deploy_pct)/100){await client.query("ROLLBACK");return res.status(409).json({error:`Order exceeds the ${policy.max_deploy_pct}% total paper capital deployment limit.`});}if(Number(a.cash)<deploy){await client.query("ROLLBACK");return res.status(409).json({error:"Insufficient available paper cash."});}}else if(!pos||Number(pos.quantity)<quantity){await client.query("ROLLBACK");return res.status(409).json({error:"Insufficient paper position to sell."});}
const orderId=randomUUID(),cashDelta=side==="BUY"?-deploy:gross-fees,cashAfter=Number(a.cash)+cashDelta;await client.query("INSERT INTO paper_orders(id,client_order_id,account_id,instrument_id,side,quantity,order_type,status,requested_price,fill_price,fees,slippage_bps) VALUES($1,$2,$3,$4,$5,$6,$7,'FILLED',$8,$9,$10,15)",[orderId,clientOrderId,a.id,i.id,side,quantity,type,requested,fill,fees]);await client.query("UPDATE paper_accounts SET cash=$1 WHERE id=$2",[cashAfter,a.id]);if(side==="BUY"){await client.query("INSERT INTO paper_fills(order_id,instrument_id,quantity,fill_price,fees,slippage_bps) VALUES($1,$2,$3,$4,$5,15)",[orderId,i.id,quantity,fill,fees]);const oldQty=pos?Number(pos.quantity):0,avg=pos?Number(pos.avg_price):0,newAvg=(oldQty*avg+gross)/(oldQty+quantity);await client.query("INSERT INTO paper_positions(account_id,instrument_id,quantity,avg_price) VALUES($1,$2,$3,$4) ON CONFLICT(account_id,instrument_id) DO UPDATE SET quantity=paper_positions.quantity+excluded.quantity,avg_price=$4",[a.id,i.id,quantity,newAvg]);}else{await client.query("INSERT INTO paper_fills(order_id,instrument_id,quantity,fill_price,fees,slippage_bps) VALUES($1,$2,$3,$4,$5,15)",[orderId,i.id,quantity,fill,fees]);const left=Number(pos.quantity)-quantity;if(left===0)await client.query("DELETE FROM paper_positions WHERE account_id=$1 AND instrument_id=$2",[a.id,i.id]);else await client.query("UPDATE paper_positions SET quantity=$1 WHERE account_id=$2 AND instrument_id=$3",[left,a.id,i.id]);}await client.query("INSERT INTO paper_ledger(account_id,order_id,entry_type,amount,cash_after) VALUES($1,$2,$3,$4,$5),($1,$2,'FEE',$6,$5)",[a.id,orderId,side==="BUY"?"BUY_DEBIT":"SELL_CREDIT",side==="BUY"?-gross:gross,cashAfter,-fees]);await client.query("INSERT INTO audit_events(actor_id,event_type,correlation_id,payload) VALUES($1,'paper.order.filled',$2,$3)",[req.userId,orderId,JSON.stringify({instrumentId:i.id,side,quantity,fill,fees})]);await client.query("COMMIT");res.status(201).json({id:orderId,clientOrderId,accountId:a.id,symbol:i.symbol,instrumentId:i.id,side,quantity,type,status:"FILLED",fillPrice:fill,fees,slippageBps:15,createdAt:new Date().toISOString(),mode:"PAPER",source:"DHAN_API"});}catch(e){await client.query("ROLLBACK");if((e as any).code==="23505"){const prior=await pool.query("SELECT o.*,i.symbol FROM paper_orders o JOIN paper_accounts a ON a.id=o.account_id JOIN instruments i ON i.id=o.instrument_id WHERE a.user_id=$1 AND o.client_order_id=$2",[req.userId,clientOrderId]);if(prior.rowCount)return res.status(200).json(prior.rows[0]);}next(e);}finally{client.release();}});
app.get("/api/v1/paper/ledger",auth,async(req:AuthedRequest,res,next)=>{try{const a=await accountFor(req.userId!);if(!a.rowCount)return res.status(404).json({error:"Paper account not found"});const r=await pool.query("SELECT l.*,o.side,o.quantity,i.symbol FROM paper_ledger l JOIN paper_orders o ON o.id=l.order_id JOIN instruments i ON i.id=o.instrument_id WHERE l.account_id=$1 ORDER BY l.created_at DESC LIMIT 200",[a.rows[0].id]);res.json(r.rows);}catch(e){next(e);}});
app.get("/api/v1/risk/policy",auth,async(req:AuthedRequest,res,next)=>{try{const r=await pool.query("SELECT max_positions AS \"maxPositions\",daily_loss_pct AS \"dailyLossPct\",max_deploy_pct AS \"maxDeployPct\" FROM risk_policies WHERE user_id=$1",[req.userId]);res.json(r.rows[0]??{maxPositions:5,dailyLossPct:2,maxDeployPct:60});}catch(e){next(e);}});
const alertSchema=z.object({instrumentId:z.string(),condition:z.enum(["ABOVE","BELOW"]),targetPrice:z.number().positive()});
app.get("/api/v1/alerts",auth,async(req:AuthedRequest,res,next)=>{try{const r=await pool.query("SELECT a.*,i.symbol,i.name FROM price_alerts a JOIN instruments i ON i.id=a.instrument_id WHERE a.user_id=$1 ORDER BY a.created_at DESC",[req.userId]);for(const a of r.rows){if(a.status!=="ACTIVE")continue;const current=await withLatestQuote(quote(a.instrument_id));if(current.source!=="DHAN_API"||!Number.isFinite(Number(current.price))||Date.now()-Date.parse(current.asOf??"")>30000)continue;const triggered=a.condition==="ABOVE"?current.price>=Number(a.target_price):current.price<=Number(a.target_price);if(triggered){a.status="TRIGGERED";a.triggered_at=new Date().toISOString();await pool.query("UPDATE price_alerts SET status='TRIGGERED',triggered_at=now() WHERE id=$1 AND user_id=$2",[a.id,req.userId]);}}res.json(r.rows);}catch(e){next(e);}});
app.post("/api/v1/alerts",auth,async(req:AuthedRequest,res,next)=>{try{const v=alertSchema.safeParse(req.body);if(!v.success)return res.status(400).json({error:"Invalid alert",details:v.error.flatten()});if(!quote(v.data.instrumentId)||quote(v.data.instrumentId)?.kind==="index")return res.status(404).json({error:"Choose a supported equity instrument"});const r=await pool.query("INSERT INTO price_alerts(user_id,instrument_id,condition,target_price) VALUES($1,$2,$3,$4) RETURNING *",[req.userId,v.data.instrumentId,v.data.condition,v.data.targetPrice]);await audit(req.userId!,"alert.created",r.rows[0].id,{instrumentId:v.data.instrumentId,condition:v.data.condition,targetPrice:v.data.targetPrice});res.status(201).json(r.rows[0]);}catch(e){next(e);}});
app.delete("/api/v1/alerts/:id",auth,async(req:AuthedRequest,res,next)=>{try{await pool.query("DELETE FROM price_alerts WHERE id=$1 AND user_id=$2",[req.params.id,req.userId]);res.status(204).end();}catch(e){next(e);}});
const backtestSchema=z.object({instrumentId:z.string(),strategy:z.enum(["sma-crossover","buy-and-hold"]).default("sma-crossover"),bars:z.number().int().min(50).max(500).default(250)});
app.get("/api/v1/research/backtests",auth,async(req:AuthedRequest,res,next)=>{try{const r=await pool.query("SELECT id,instrument_id AS \"instrumentId\",strategy,parameters,result,source,created_at AS \"createdAt\" FROM backtest_runs WHERE user_id=$1 ORDER BY created_at DESC LIMIT 50",[req.userId]);res.json(r.rows);}catch(e){next(e);}});
app.post("/api/v1/research/backtests",auth,async(req:AuthedRequest,res,next)=>{try{const v=backtestSchema.safeParse(req.body);if(!v.success)return res.status(400).json({error:"Invalid backtest request",details:v.error.flatten()});const instrument=quote(v.data.instrumentId);if(!instrument||instrument.kind==="index")return res.status(404).json({error:"Choose a supported equity instrument"});const history=await pool.query("SELECT close FROM market_bars_1m WHERE instrument_id=$1 AND quality_status='VALID' ORDER BY event_time DESC LIMIT $2",[instrument.id,v.data.bars]);if(history.rows.length<v.data.bars)return res.status(409).json({error:"Import enough licensed Dhan historical bars before running a backtest."});const points=history.rows.reverse().map(row=>Number(row.close));const sma=(end:number,period:number)=>points.slice(end-period+1,end+1).reduce((a,b)=>a+b,0)/period;let holding=false,entry=0,cash=100000,shares=0,fees=0,trades=0,wins=0,peak=100000,maxDrawdown=0;const costRate=.002;for(let n=20;n<points.length;n++){const price=points[n];if(v.data.strategy==="buy-and-hold"&&n===20){shares=Math.floor(cash/price);const spend=shares*price;fees+=spend*costRate;cash-=spend+spend*costRate;holding=true;entry=price;}else if(v.data.strategy==="sma-crossover"){const enter=sma(n,5)>sma(n,20),exit=sma(n,5)<sma(n,20);if(!holding&&enter){shares=Math.max(1,Math.floor(cash*.6/price));const spend=shares*price;fees+=spend*costRate;cash-=spend+spend*costRate;holding=true;entry=price;}else if(holding&&exit){const proceeds=shares*price;fees+=proceeds*costRate;cash+=proceeds-proceeds*costRate;trades++;if(price>entry)wins++;shares=0;holding=false;}}const equity=cash+shares*price;peak=Math.max(peak,equity);maxDrawdown=Math.max(maxDrawdown,(peak-equity)/peak);}const finalEquity=cash+shares*points.at(-1)!,result={initialCapital:100000,finalEquity:Number(finalEquity.toFixed(2)),netReturnPct:Number(((finalEquity/100000-1)*100).toFixed(2)),maxDrawdownPct:Number((maxDrawdown*100).toFixed(2)),closedTrades:trades,winRatePct:trades?Number((wins/trades*100).toFixed(1)):null,estimatedCosts:Number(fees.toFixed(2)),bars:points.length,disclaimer:"Dhan historical candles with simplified fills and fixed estimated costs; not a validated strategy. No point-in-time events, current statutory charges, corporate actions, survivorship controls, exchange queue, or realistic partial-fill model are included."};const run=await pool.query("INSERT INTO backtest_runs(user_id,instrument_id,strategy,parameters,result,source) VALUES($1,$2,$3,$4,$5,'DHAN_HISTORICAL') RETURNING id,created_at",[req.userId,instrument.id,v.data.strategy,JSON.stringify({bars:v.data.bars,costRate}),JSON.stringify(result)]);await audit(req.userId!,"research.backtest.created",run.rows[0].id,{instrumentId:instrument.id,strategy:v.data.strategy});res.status(201).json({id:run.rows[0].id,instrumentId:instrument.id,symbol:instrument.symbol,strategy:v.data.strategy,createdAt:run.rows[0].created_at,result,source:"DHAN_HISTORICAL"});}catch(e){next(e);}});
